/* EVE Language Definition for PrismJS */
Prism.languages.eve={
	comment:{
		pattern:/(?:#.*|\/\*[\s\S]*?\*\/|\*\*[^\n]*)/,
		greedy:true
	},
	string:{
		pattern:/"(?:\\.|[^"\\])*"/,
		greedy:true
	},
	character:{
		pattern:/'(?:\\.|[^'\\])'/,
		greedy:true
	},
	number:/\b\d+\.?\d*\b/,
	type:/\b(?:Byte|Short|Integer|Natural|Real|Float|Rational|String|Logic|Table|Rune|Record|Decimal|Huge|Ordinal|Variant|Date|Time|Array|List|Object|Class|Lambda|Function|DataSet|DataMap|Folder|File)\b/,
	boolean:/\b(?:true|false|True|False|Null|null)\b/i,
	constant:/\b(?:any|other|all|one|label|self|args|super)\b/,
	keyword:/\b(?:import|alias|class|global|constant|return|create|release|method|function|procedure|generator|export|public|private|protected|service|route|routine|driver|module|aspect|exclusive|concurrent|recover|finalize|process|initialize|shell|session|update|append|commit|from|use|in|is|as|or|eq|and|not|new|let|set|scrub|delete|repeat|when|job|case|on|loop|while|for|task|try|miss|match|if|then|catch|else|done|expect|break|halt|alter|make|store|apply|start|spawn|await|async|yield|run|call|wait|exit|stop|print|write|read|over|panic|pass|skip|fail|raise|retry|resume|synchronise|rollback|do)\b/,
	operator:/(?:::=|==|!=|=>|:>|<:|<-|->|\.\.\.|\.\.|\*=|\/=|-=|\+=|\^=|%=|<=|>=|<<|>>|<\+|\+>|[@:=><+\-/*&|#?;])/,
	punctuation:/[{}()\[\],.:]/
};
